   "constraints": [
    "value >= 0.0"
   ]
  },
  {
   "name": "min_created_at",
   "type": "string",
   "required": false,
   "description": "Filter emails by minimum created_at date in YYYY-MM-DD format.",
   "default": "1500-01-01",
   "constraints": []
  },
  {
   "name": "max_created_at",
   "type": "string",
   "required": false,
   "description": "Filter emails by maximum created_at date in YYYY-MM-DD format.",
   "default": "3000-01-01",
   "constraints": []
  },
  {
   "name": "deleted",
   "type": "boolean",
   "required": false,
   "description": "Whether to limit the results to expenses marked as deleted or not.",
   "default": false,
   "constraints": []
  },
  {
   "name": "page_index",
